const input = $input.first().json || {};
const runType = String(input.requestedRunType || input.runType || '').toUpperCase();
const cfg = input.centralConfig || {};
const globalCfg = cfg.globalConfig || {};
const channels = cfg.channels || {};
const groqApiKey = globalCfg.groqApiKey || '';
const groqModel = globalCfg.groqModel || 'llama-3.3-70b-versatile';
const channelKey = input.channelKey || 'localStackAi';
const channel = channels[channelKey] || {};
const niche = channel.niche || 'AI automation for local businesses';
const nicheKeywords = channel.nicheKeywords || 'local business automation';
const mainOfferUrl = channel.mainOfferUrl || globalCfg.mainOfferUrl || '';
const offerCatalog = channel.offerCatalog || [];
const isDemo = !groqApiKey || groqApiKey === '' || groqApiKey.startsWith('demo-');
if (runType !== 'WEEKLY_STRATEGY' && runType !== 'MILESTONE_CHECK') {
  return [{ json: { ...input, status: 'STRATEGY_SKIPPED', strategySummary: 'Unsupported strategy runType: ' + (runType || 'UNKNOWN'), completedAt: new Date().toISOString() } }];
}
// Revenue milestone targets
const milestoneTargets = [
  { subscribers: 100, label: 'First 100', revenueEstimate: '$0/mo', action: 'Focus purely on output: 3 vids/wk, no CTA needed yet' },
  { subscribers: 500, label: '500 Club', revenueEstimate: '$50-100/mo', action: 'Add pinned CTA to every description. Start email list.' },
  { subscribers: 1000, label: 'Monetised', revenueEstimate: '$100-300/mo', action: 'Enable YouTube Partner. Push lead magnet hard.' },
  { subscribers: 2500, label: 'Scale Phase', revenueEstimate: '$300-600/mo', action: 'Add mid-roll ads, launch paid guide, promote in pinned comment.' },
  { subscribers: 5000, label: '5K Milestone', revenueEstimate: '$600-1500/mo', action: 'Launch community, sponsorships, upsell to consultation.' },
  { subscribers: 10000, label: '10K Authority', revenueEstimate: '$1500-4000/mo', action: 'Affiliate partnerships, high-ticket offer, courses.' }
];
const weeklySystemPrompt = 'You are a YouTube channel strategist for niche: "' + niche + '". Keywords: ' + nicheKeywords + '. Offer catalog: ' + JSON.stringify(offerCatalog.map(o => o.label)) + '. Output valid JSON only.';
const weeklyUserPrompt = 'Generate a weekly strategy brief. Return JSON with these keys: weekTheme (string), contentPlan (array of 3 objects with day/title/format/hook/offerFit/priorityReason), gapOpportunities (array of 3 objects with topic/reason/gapScore 0-100), revenueStrategy (object with primaryCTA/ctaPlacement/expectedClickRate/offerRecommended), thumbnailTrend (string), postingSchedule (string), subscriberGrowthTip (string).';
const milestoneSystemPrompt = 'You are a YouTube channel growth analyst for niche: "' + niche + '". Output valid JSON only.';
const milestoneUserPrompt = 'Milestone targets: ' + JSON.stringify(milestoneTargets.slice(0, 4)) + '. Return JSON with: currentPhase, nextMilestone (object with subscribers/label/action), velocityNeeded (string, subs/day to hit next milestone in 30 days), contentFrequencyRecommended, revenueUnlockAt, topPriorityAction, milestoneTimeline (array of objects with milestone/estimatedWeeks/keyAction).';
const prompt = runType === 'WEEKLY_STRATEGY' ? weeklyUserPrompt : milestoneUserPrompt;
const systemMsg = runType === 'WEEKLY_STRATEGY' ? weeklySystemPrompt : milestoneSystemPrompt;
let strategyData = null;
let aiStatus = 'DEMO';
if (!isDemo) {
  try {
    const resp = await fetch('https://api.groq.com/openai/v1/chat/completions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + groqApiKey },
      body: JSON.stringify({ model: groqModel, messages: [{ role: 'system', content: systemMsg }, { role: 'user', content: prompt }], temperature: 0.6, max_tokens: 1600, response_format: { type: 'json_object' } })
    });
    if (!resp.ok) throw new Error('Groq ' + resp.status + ': ' + (await resp.text()).slice(0, 300));
    const r = await resp.json();
    strategyData = JSON.parse(r.choices?.[0]?.message?.content || '{}');
    aiStatus = 'GROQ_LIVE';
  } catch(e) {
    strategyData = { _groqError: String(e.message || e) };
    aiStatus = 'GROQ_ERROR';
  }
}
const keywords = nicheKeywords.split(',').map(k => k.trim()).filter(Boolean);
const focusTopic = keywords[0] || niche;
if (!strategyData || aiStatus === 'DEMO') {
  if (runType === 'WEEKLY_STRATEGY') {
    strategyData = {
      weekTheme: focusTopic,
      contentPlan: [
        { day: 'Monday', title: '3 free tools for ' + niche + ' (most businesses miss these)', format: 'long-form', hook: 'You are paying for tools you do not need', offerFit: (offerCatalog[0] || {}).label || 'guide', priorityReason: 'High search volume + low competition' },
        { day: 'Wednesday', title: '60-second ' + focusTopic + ' tip', format: 'shorts', hook: 'This one change saved 3h/week', offerFit: (offerCatalog[0] || {}).label || 'guide', priorityReason: 'Shorts drive subscriber spikes with zero extra work' },
        { day: 'Friday', title: 'Full walkthrough: ' + focusTopic + ' system for service businesses', format: 'tutorial', hook: 'Watch me build the whole thing live', offerFit: (offerCatalog[1] || {}).label || 'playbook', priorityReason: 'Tutorials drive highest watch time and offer conversions' }
      ],
      gapOpportunities: [
        { topic: niche + ' for solopreneurs', reason: 'Most content targets agencies, not solos', gapScore: 84 },
        { topic: 'Free vs paid: real comparison for ' + focusTopic, reason: 'Comparison content drives high-intent traffic', gapScore: 79 },
        { topic: 'Before/after automation case study', reason: 'Story-format builds trust and drives conversions', gapScore: 77 }
      ],
      revenueStrategy: {
        primaryCTA: (offerCatalog[0] || {}).cta || 'Get the free guide',
        ctaPlacement: 'Pinned comment + video description + mid-roll at 40% mark',
        expectedClickRate: '2-4% of views',
        offerRecommended: (offerCatalog[0] || {}).label || 'Free guide'
      },
      thumbnailTrend: 'Split before/after, large bold text, real person face showing emotion, high contrast',
      postingSchedule: 'Mon long-form + Wed Shorts + Fri tutorial — 10am viewer timezone',
      subscriberGrowthTip: 'End every video with a direct subscribe ask targeting your niche: "Subscribe if you run a service business" — specific asks convert 3x better than generic ones'
    };
  } else {
    strategyData = {
      currentPhase: 'Launch Phase (0-500 subs)',
      nextMilestone: milestoneTargets[0],
      velocityNeeded: '4 subs/day to hit 100 in 25 days',
      contentFrequencyRecommended: '3 videos/week (2 long-form + 1 Short)',
      revenueUnlockAt: '1,000 subscribers (YouTube Partner Program)',
      topPriorityAction: 'Publish 3 videos this week — volume beats perfection in early stage. Use CONTENT_DAILY run for ideas.',
      milestoneTimeline: milestoneTargets.slice(0, 4).map((m, i) => ({ milestone: m.label, estimatedWeeks: (i + 1) * 4, keyAction: m.action }))
    };
  }
}
const status = runType === 'WEEKLY_STRATEGY' ? 'WEEKLY_STRATEGY_COMPLETE' : 'MILESTONE_CHECK_COMPLETE';
return [{ json: {
  ...input,
  status,
  aiStatus,
  runType,
  channelKey,
  strategyData,
  milestoneTargets,
  strategySummary: runType + ' completed [' + aiStatus + '] for ' + channelKey,
  completedAt: new Date().toISOString(),
  workflowPackVersion: input.workflowPackVersion || 'v24'
} }];
